SELECT CASE WHEN YEAR(order_date) < 2024 THEN 'before_2024' WHEN YEAR(order_date) = 2024 THEN '2024' ELSE 'after_2024' END AS order_cohort, channel, COUNT(DISTINCT discount) AS unique_statuss, MAX(discount) AS max_discount, AVG(amount) AS avg_amount FROM orders WHERE status <> 'PENDING' AND status IN ('RETURNED', 'COMPLETED') AND shipping_fee BETWEEN 17 AND 27 GROUP BY order_cohort, channel HAVING COUNT(CASE WHEN status = 'SHIPPED' THEN 1 END) > 3 ORDER BY order_cohort DESC, unique_statuss;
